import {NAV,localDate,dailyIndex,escapeHtml as esc,matchQuery,makeId,validateBackup,mergeNotes,noteMarkdown} from './core.mjs';
import * as db from './storage.mjs';
import {experiments,experimentMarkup,mountExperiment} from './experiments.mjs';
import {readEpub} from './epub.mjs';

const $=s=>document.querySelector(s);
const state={lessons:[],terms:[],sources:[],notes:[],prefs:{theme:'light',font:'normal',completed:[],bookmarks:[]},files:[],storage:true,filter:'All',readingSearch:'',glossarySearch:'',noteSearch:'',offline:false,native:navigator.userAgent.includes('LudwigAndroid/'),installPrompt:null,registration:null,sourceTarget:null,objectUrls:[],saveQueue:Promise.resolve(),saveError:false};
const main=$('#main'),modal=$('#modal');
const icons={home:'<path d="m3 10 9-7 9 7v11H3zM9 21v-8h6v8"/>',book:'<path d="M12 5c-3-2-6-2-10-1v15c4-1 7-1 10 1 3-2 6-2 10-1V4c-4-1-7-1-10 1v15"/>',spark:'<path d="m12 2 2.5 7.5L22 12l-7.5 2.5L12 22l-2.5-7.5L2 12l7.5-2.5z"/>',sun:'<circle cx="12" cy="12" r="4"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/>',type:'<path d="M3 5V3h18v2M12 3v18M7 21h10"/>',library:'<path d="M3 3h4v18H3zM10 3h4v18h-4zM17 4l4-1 4 17-4 1z"/>',pen:'<path d="m15 3 6 6M3 21l5-1L22 6l-6-5L2 15zM2 15l6 5"/>'};
const icon=name=>`<svg viewBox="0 0 24 24" aria-hidden="true">${icons[name]||icons.book}</svg>`;
const sourceName=id=>({pi:'PI','pi-bilingual':'PI (DE/EN)',tractatus:'TLP',certainty:'OC','blue-brown':'Blue & Brown Books',grammar:'Philosophical Grammar',colour:'Remarks on Colour',voices:'Voices',ethics:'Lecture on Ethics','free-will':'Freedom of the Will','private-experience':'Private Experience',philosophy:'Philosophy','notes-logic':'Notes on Logic','language-use':'Frazer remarks',peacocke:'Peacocke',sep:'SEP'}[id]||state.sources.find(s=>s.id===id)?.title||id);
const lessonById=id=>state.lessons.find(l=>l.id===id);
const termById=id=>state.terms.find(t=>t.id===id);
const para=text=>String(text??'').split(/\n\s*\n/).filter(Boolean).map(t=>`<p>${esc(t).replace(/\n/g,'<br>')}</p>`).join('');
const refs=(items=[],compact=false)=>items.map(r=>`<button class="citation-chip" data-action="citation" data-source="${esc(r.source)}" data-locator="${esc(r.locator)}" ${r.note?`data-note="${esc(r.note)}"`:''}>${esc(sourceName(r.source))} ${esc(r.locator)}${compact?'':' ↗'}</button>`).join('');
const niceDate=value=>{const date=new Date(value.includes('T')?value:value+'T12:00:00');return Number.isNaN(date.valueOf())?'':new Intl.DateTimeFormat(undefined,{month:'short',day:'numeric',year:'numeric'}).format(date);};
const today=()=>state.lessons[dailyIndex(state.lessons.length)];
const progress=()=>state.lessons.length?Math.round(state.prefs.completed.filter(id=>lessonById(id)).length/state.lessons.length*100):0;
function toast(text){$('#toast').textContent=text;$('#toast').classList.add('visible');clearTimeout(state.toastTimer);state.toastTimer=setTimeout(()=>$('#toast').classList.remove('visible'),4200);}
function openModal(label,html){state.modalRevision=(state.modalRevision||0)+1;cleanupUrls();$('#modal-label').textContent=label;$('#modal-body').innerHTML=html;modal.scrollTop=0;if(!modal.open)modal.showModal();}
function cleanupUrls(){for(const url of state.objectUrls)URL.revokeObjectURL(url);state.objectUrls=[];}
function closeModal(){modal.close();cleanupUrls();}
modal.addEventListener('close',cleanupUrls);
modal.addEventListener('click',e=>{if(e.target===modal){const r=modal.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
function applyPrefs(){const theme=state.prefs.theme==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):state.prefs.theme;document.body.dataset.theme=theme;document.body.dataset.font=state.prefs.font;}
async function savePrefs(){applyPrefs();try{await db.putPreferences(state.prefs);}catch{toast('Your preference could not be saved. Device storage may be full.');}}
function navMarkup(route,mobile=false){const short={home:'Home',readings:'Read',explore:'Explore',daily:'Today',notebook:'Notes'};return NAV.filter(n=>!mobile||['home','readings','explore','daily','notebook'].includes(n[0])).map(([id,title,name])=>`<a class="nav-link ${(route===id||(route==='read'&&id==='readings'))?'active':''}" href="#/${id}" ${(route===id||(route==='read'&&id==='readings'))?'aria-current="page"':''}>${icon(name)}<span>${mobile?short[id]:title}</span></a>`).join('');}
function pageHead(kicker,title,description){return `<div class="page-head"><span class="eyebrow">${esc(kicker)}</span><h1>${esc(title)}</h1>${description?`<p>${esc(description)}</p>`:''}</div>`;}
function lessonCard(l){return `<a class="reading-card" href="#/read/${esc(l.id)}"><span class="eyebrow">${esc(l.category)} · ${esc(l.period)}</span><h2>${esc(l.title)}</h2><p>${esc(l.subtitle)}</p><div class="card-bottom"><span>${l.readingMinutes} MIN READ${state.prefs.completed.includes(l.id)?' · ✓ READ':''}${state.prefs.bookmarks.includes(l.id)?' · SAVED':''}</span><span class="arrow">↗</span></div></a>`;}

function renderHome(){const idea=today(),last=lessonById(state.prefs.lastLesson),date=new Intl.DateTimeFormat(undefined,{weekday:'long',month:'long',day:'numeric'}).format(new Date());return `<div class="page-kicker"><span>A COMPANION TO WITTGENSTEIN</span><span>${esc(date)}</span></div><section class="hero"><div class="hero-copy"><span class="eyebrow">PHILOSOPHY BEGINS WITH ATTENTION</span><h1>A little less certain.<br><em>A little more curious.</em></h1><p>Make room for a different way of seeing. Explore Ludwig Wittgenstein’s ideas, one ordinary moment at a time.</p><a class="button" href="#/read/${last?.id||'begin'}">${last?'Continue exploring':'Begin with Ludwig'} <span>↗</span></a></div><div class="hero-art"><img src="./assets/portrait.webp" alt="An original illustration of a thoughtful Wittgenstein beside a window overlooking a Norwegian fjord" fetchpriority="high"><span class="image-caption">An imagined scene · original illustration</span></div></section><div class="home-columns"><section><div class="section-heading"><h2>A thought for today</h2><a class="text-link" href="#/daily">Take a moment ↗</a></div><article class="daily-card"><span class="eyebrow">${esc(idea.category)} · ${esc(localDate())}</span><h3>${esc(idea.title)}</h3><p>${esc(idea.summary)}</p><div class="daily-meta"><span>${idea.readingMinutes} MIN READ</span><span>${esc(sourceName(idea.sourceRefs?.[0]?.source))} ${esc(idea.sourceRefs?.[0]?.locator||'')}</span></div><a class="text-link" href="#/daily">Sit with this idea <span>→</span></a></article></section><section><div class="section-heading"><h2>Find your way in</h2></div><div class="path-mini">${[['01','meaning-use','Words in use','Start with the familiar'],['02','going-on','How to go on','Rules, learning & practice'],['03','hinges','What we rely on','Knowledge & certainty']].map(([n,id,title,sub])=>`<a href="#/read/${id}"><span class="path-num">${n}</span><span><h4>${title}</h4><small>${sub}</small></span><span class="arrow">↗</span></a>`).join('')}</div><div class="continue-row"><p>${progress()?`You’ve explored ${state.prefs.completed.length} readings.`:'No background in philosophy needed.'}<br><span class="muted">Follow a question. Take your time.</span></p><a class="text-link" href="#/readings">All readings ↗</a></div></section></div><section class="home-workshop"><div class="section-heading"><h2>Think by trying</h2><a class="text-link" href="#/explore">The workshop ↗</a></div><div class="workshop-preview"><img src="./assets/practices.webp" alt="An imagined village of people building, talking, trading, and playing: shared activities of ordinary language" loading="lazy"><div><span class="eyebrow">IDEAS YOU CAN EXPERIMENT WITH</span><h3>What changes when we look again?</h3><p>Try a word in a new setting, continue a sequence, or see the same drawing differently. Then ask what you noticed.</p><a class="text-link" href="#/explore">Step into the workshop →</a></div></div></section><div class="continue-row"><p>A dictionary, a bookshelf, and room for your own thoughts.</p><div style="display:flex;gap:20px;flex-wrap:wrap"><a class="text-link" href="#/glossary">Words & meanings ↗</a><a class="text-link" href="#/sources">The bookshelf ↗</a></div></div>`;}

function renderReadings(){const categories=['All','Language','Knowledge','Mind','Ethics','Method','Logic','Saved'];const list=state.lessons.filter(l=>(state.filter==='All'||(state.filter==='Saved'?state.prefs.bookmarks.includes(l.id):l.category===state.filter))&&matchQuery(state.readingSearch,l.title,l.subtitle,l.summary,l.category,l.period));return `${pageHead('GO SLOW. LOOK CLOSELY.','Guided readings','Plain-language routes into difficult ideas. Begin anywhere, or follow the readings in order. Each opens into examples, objections, questions, and sources.')}<div class="path-intro"><div><strong>${state.lessons.length} readings · ${progress()}% explored</strong><p>Start with “A different way of looking.” When a word feels unfamiliar, open its definition beside the reading.</p><div class="progress-bar" style="margin-top:13px"><span style="width:${progress()}%"></span></div></div></div><label class="form-label" for="reading-search">Find a reading</label><input class="search-field" id="reading-search" type="search" placeholder="Meaning, pain, certainty, how to go on…" value="${esc(state.readingSearch)}"><div class="filters" role="group" aria-label="Filter readings">${categories.map(c=>`<button class="filter ${state.filter===c?'active':''}" data-action="filter" data-filter="${c}" aria-pressed="${state.filter===c}">${c}</button>`).join('')}</div><div class="reading-grid" id="reading-results">${list.length?list.map(lessonCard).join(''):'<div class="empty"><h2>No readings here yet.</h2><p>Try a different word or choose All.</p></div>'}</div>`;}

function renderReader(id){const l=lessonById(id);if(!l)return notFound();state.prefs.lastLesson=l.id;void savePrefs();const sections=l.sections.map((s,i)=>`<section class="reader-section" id="section-${i}"><h2>${esc(s.title)}</h2>${para(s.body)}<button class="section-note" data-action="section-note" data-lesson="${esc(l.id)}" data-section="${i}">＋ Keep a thought about this section</button></section>`).join('');const termEntries=(l.terms||[]).map(termById).filter(Boolean);const saved=state.prefs.bookmarks.includes(l.id);return `<div class="reading-progress" id="reading-progress"></div><a class="back-link" href="#/readings">← Guided readings</a><div class="reader-layout"><article class="reader-main"><span class="eyebrow">${esc(l.period)} WITTGENSTEIN · ${esc(l.category)}</span><h1>${esc(l.title)}</h1><p class="reader-deck">${esc(l.subtitle)}</p><div class="reading-tools"><button class="button secondary" data-action="bookmark" data-lesson="${esc(l.id)}">${saved?'✓ Saved reading':'＋ Save reading'}</button><button class="button secondary" data-action="new-note" data-lesson="${esc(l.id)}">Write a note</button><button class="button secondary" data-action="reader-settings">Aa</button></div><div class="reader-meta"><span>${l.readingMinutes} MIN READ</span><span>ORIGINAL EXPLANATION · SOURCE REFERENCES BELOW</span></div><div class="reader-prose"><p style="margin-top:27px">${esc(l.summary)}</p>${sections}<section class="takeaway-box" id="takeaways"><h2>Carry this with you</h2><ul>${l.takeaways.map(t=>`<li>${esc(t)}</li>`).join('')}</ul></section><section id="questions"><h2>Questions to keep open</h2><ol class="question-list">${l.questions.map(q=>`<li>${esc(q)}</li>`).join('')}</ol></section>${l.exercise?`<section class="exercise" id="exercise"><span class="eyebrow">TRY IT IN YOUR OWN LIFE</span><h2>${esc(l.exercise.title)}</h2>${para(l.exercise.prompt)}<div class="exercise-options">${l.exercise.options.map((o,i)=>`<button data-action="exercise-answer" data-lesson="${esc(l.id)}" data-option="${i}">${esc(o.text)}</button>`).join('')}</div><div id="exercise-feedback" role="status"></div><p>${esc(l.exercise.reflection)}</p><button class="button" data-action="reflection" data-lesson="${esc(l.id)}">Reflect in my notebook ↗</button></section>`:''}</div><section id="terms"><h2 style="font-size:25px">Words along the way</h2>${termEntries.length?termEntries.map(t=>`<button class="term-chip" data-action="term" data-term="${esc(t.id)}">${esc(t.german)} · ${esc(t.english)}</button>`).join(''):'<a class="text-link" href="#/glossary">Open words & meanings ↗</a>'}</section><section id="citations" class="source-note"><h2 style="font-size:25px">Return to the text</h2><p>These readings are explanations and comparisons, not a substitute for the text. Open a reference to see its edition and context. § means a numbered remark; §§ means several remarks. An unnumbered PDF page is not a printed page.</p>${refs(l.sourceRefs)}<p style="margin-top:15px">For an academic paper, read the surrounding passages and check your required citation style. Local source imports remain available on this device.</p></section><div class="reader-finish"><button class="button" data-action="complete" data-lesson="${esc(l.id)}">${state.prefs.completed.includes(l.id)?'✓ Marked as explored':'Mark as explored ✓'}</button><button class="button secondary" data-action="new-note" data-lesson="${esc(l.id)}">Keep a thought</button></div><div class="related-grid"><h2>Follow another thread</h2>${(l.related||[]).map(lessonById).filter(Boolean).map(r=>`<a href="#/read/${esc(r.id)}">${esc(r.title)} <span style="float:right">↗</span></a>`).join('')}</div></article><aside class="reader-aside"><div class="reader-sticky"><div class="aside-block"><h3>In this reading</h3><nav class="toc" aria-label="Reading sections">${l.sections.map((s,i)=>`<a href="#/read/${esc(l.id)}" data-action="scroll-section" data-section="section-${i}">${esc(s.title)}</a>`).join('')}<a href="#/read/${esc(l.id)}" data-action="scroll-section" data-section="takeaways">Takeaways</a><a href="#/read/${esc(l.id)}" data-action="scroll-section" data-section="questions">Questions</a></nav></div><div class="aside-block"><h3>The source trail</h3>${refs(l.sourceRefs,true)}</div><div class="aside-block"><h3>Words & meanings</h3>${termEntries.map(t=>`<button class="term-chip" data-action="term" data-term="${esc(t.id)}">${esc(t.german)}</button>`).join('')}</div><p class="fineprint">Select a passage, then use “Write a note” to keep it with a link back here.</p></div></aside></div>`;}

function renderExplore(id){if(id&&experiments.some(e=>e.id===id))return `<a class="back-link" href="#/explore">← The workshop</a><div class="experiment-stage" id="experiment-stage">${experimentMarkup(id)}</div>`;return `${pageHead('THINK BY TRYING','The workshop','Ideas become clearer when we do something with them. These small experiments are invitations to compare, notice, and ask again.')}<div class="workshop-grid">${experiments.map(e=>`<a class="experiment-card" href="#/explore/${e.id}"><span class="experiment-mark" aria-hidden="true">${e.mark}</span><span class="eyebrow">${e.tag}</span><h2>${e.title}</h2><p>${e.description}</p><span class="text-link">Try the experiment →</span></a>`).join('')}</div><p class="fineprint" style="margin-top:24px">The workshop uses original teaching comparisons. Each includes a source trail and explains where the comparison has limits.</p>`;}

function renderDaily(){const l=today(),question=l.questions[dailyIndex(l.questions.length,localDate())],existing=state.notes.find(n=>n.title===`Daily thought · ${localDate()}`);return `<div class="daily-page"><div class="page-kicker"><span>A LITTLE, EVERY DAY</span><span>${esc(niceDate(localDate()))}</span></div><section class="daily-banner"><div class="daily-banner-head"><span class="eyebrow">TODAY’S INVITATION · ${esc(l.category)}</span><h1>${esc(l.title)}</h1><p class="muted" style="margin-bottom:0">${esc(l.subtitle)}</p></div><div class="daily-banner-body"><p>${esc(l.summary)}</p><span class="eyebrow" style="margin-top:28px">A QUESTION TO SPEND TIME WITH</span><div class="daily-question">${esc(question)}</div><div class="info-banner"><strong>Try this today</strong><p>${esc(l.exercise.reflection)}</p></div><div class="reading-tools"><a class="button" href="#/read/${esc(l.id)}">Read more deeply ↗</a><button class="button secondary" data-action="daily-note" data-lesson="${esc(l.id)}">${existing?'Return to today’s note':'Keep today’s thought'}</button></div>${refs(l.sourceRefs)}<p class="daily-foot">A different reading appears each day, using your device’s date. Past reflections stay in your notebook. There are no notifications or streaks to keep up with.</p></div></section></div>`;}

function renderGlossary(){const entries=state.terms.filter(t=>matchQuery(state.glossarySearch,t.german,t.english,t.definition,t.nuance));return `${pageHead('GERMAN, ENGLISH, AND THE SPACE BETWEEN','Words & meanings','A word can guide us, or lead us astray. Explore the everyday background of Wittgenstein’s vocabulary and what a translation can bring into focus.')}<div class="info-banner"><p>The German is often the original, rather than a translation of English. The Blue and Brown Books were dictated in English; the Lecture on Ethics was delivered in English. A German equivalent is not automatically an original technical term.</p></div><label class="form-label" for="glossary-search">Find a word or idea</label><input class="search-field" id="glossary-search" type="search" value="${esc(state.glossarySearch)}" placeholder="Sprachspiel, meaning, grammar, knowledge…"><div class="term-grid" id="term-results">${entries.length?entries.map(termCard).join(''):'<div class="empty">No matching terms. Try a broader word.</div>'}</div>`;}
function termCard(t){return `<button class="term-card" data-action="term" data-term="${esc(t.id)}"><h2>${esc(t.german)}</h2><p class="translation">${esc(t.english)}</p><p>${esc(t.definition)}</p></button>`;}
function showTerm(id){const t=termById(id);if(!t)return;openModal('Words & meanings',`<div class="modal-prose"><span class="eyebrow">A CLOSER LOOK AT A WORD</span><h2 class="term-big">${esc(t.german)}</h2><p style="color:var(--clay)">${esc(t.english)}</p><p class="term-definition">${esc(t.definition)}</p><h3>What the translation brings out</h3><div class="term-nuance">${para(t.nuance)}</div><h3>Bring it into focus</h3>${para(t.example)}<h3>Read it in context</h3>${refs(t.sourceRefs)}${(t.related||[]).map(lessonById).filter(Boolean).map(l=>`<a class="search-result" href="#/read/${esc(l.id)}"><h3>${esc(l.title)} ↗</h3><p>${esc(l.subtitle)}</p></a>`).join('')}<div class="modal-actions"><button class="button secondary" data-action="term-note" data-term="${esc(t.id)}">Keep a thought</button></div></div>`);}

function renderSources(){return `${pageHead('THE IDEAS HAVE A HISTORY','The bookshelf','Read with Wittgenstein, not just about him. Follow the source trail, compare editions, and keep your own copies here for offline reading.')}<div class="info-banner"><p><strong>Your source files, on your device.</strong> Import a PDF or EPUB next to its matching work. It is stored locally and never sent to the app’s server. The app’s original readings and illustrations are included offline; full books are imported separately.</p><p>EPUBs open in a simple text reader. PDFs use your browser’s viewer, with an option to open a copy in your usual reader. Your backup contains notes and reading progress; source files need their own copies.</p></div><div class="source-grid">${state.sources.map(s=>`<article class="source-card"><div class="book-cover" aria-hidden="true">${esc(s.title)}</div><span class="eyebrow" style="font-size:8px">${esc(s.kind)}</span><h2>${esc(s.title)}</h2><p class="source-author">${esc(s.author)} · ${esc(s.year)}</p><p>${esc(s.description)}</p>${s.id==='teaching-purpose'?`<div class="warning-note">This is about Thomas E. Ludwig, not Ludwig Wittgenstein. Included to account for every file in your folder; it is not evidence for Wittgenstein’s views.</div>`:''}<div class="source-meta">${state.files.includes(s.id)?'✓ Your copy is on this device':s.id==='sep'?'Contextual online reference':'Your original is linked below'}</div><div class="source-actions"><button class="button secondary" data-action="source-detail" data-source="${esc(s.id)}">Source & context</button>${s.id!=='sep'?`<button class="button ${state.files.includes(s.id)?'':'secondary'}" data-action="${state.files.includes(s.id)?'open-file':'import-source'}" data-source="${esc(s.id)}">${state.files.includes(s.id)?'Read my copy':'Import my copy'}</button>`:''}<a class="text-link" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Original ↗</a></div></article>`).join('')}</div>`;}
function sourceDetail(id,locator='',note=''){const s=state.sources.find(s=>s.id===id);if(!s)return;openModal('The source trail',`<div class="modal-prose"><span class="eyebrow">${esc(s.kind)}</span><h2>${esc(s.title)}</h2><p class="muted">${esc(s.author)} · ${esc(s.year)}</p>${locator?`<div class="citation-detail"><h3>${esc(sourceName(s.id))} ${esc(locator)}</h3>${note?para(note):''}<p>Read the passage with its surrounding remarks. This locator refers to the text, not a claim that every sentence of our explanation appears there.</p></div>`:''}<p>${esc(s.edition)}</p><h3>How this source is used</h3>${para(s.description)}<p><strong>Checked:</strong> ${esc(s.readStatus)}</p>${s.caveat?`<div class="warning-note">${esc(s.caveat)}</div>`:''}${(s.sections||[]).map(section=>`<h3>${esc(section.label)}</h3><p style="color:var(--clay)">${esc(section.locator)}</p>${para(section.summary)}`).join('')}<div class="settings-section"><h3>A reference to adapt</h3><p>${esc(s.author)} (${esc(s.year)}). <em>${esc(s.title)}</em>. ${esc(s.edition)}</p><p class="fineprint">This records the checked source identity. Follow your institution’s citation style and use the publication year of the edition you actually consult.</p><button class="button secondary" data-action="copy-citation" data-source="${esc(s.id)}" data-locator="${esc(locator)}">Copy reference</button></div><div class="modal-actions">${state.files.includes(s.id)?`<button class="button" data-action="open-file" data-source="${esc(s.id)}">Read my local copy</button><button class="button secondary" data-action="remove-file" data-source="${esc(s.id)}">Remove local copy</button>`:s.id!=='sep'?`<button class="button secondary" data-action="import-source" data-source="${esc(s.id)}">Import my copy</button>`:''}<a class="button secondary" href="${esc(s.url)}" target="_blank" rel="noopener noreferrer">Open original online ↗</a></div></div>`);}

function renderNotebook(id){const list=state.notes.filter(n=>matchQuery(state.noteSearch,n.title,n.body,n.lesson,n.updated)).sort((a,b)=>b.updated.localeCompare(a.updated));const n=state.notes.find(n=>n.id===id)||list[0];return `<div class="notebook-top">${pageHead('KEEP THE QUESTION OPEN','Your notebook','Fragments, questions, and ways of seeing. Kept on this device.')}<button class="button" data-action="new-note">＋ A new thought</button></div>${!state.storage?'<div class="warning-note">Local storage is unavailable. Reading works, but notes cannot be saved. Enable browser storage and reload.</div>':''}<label class="form-label" for="note-search">Find a thought</label><input class="search-field" id="note-search" type="search" placeholder="Search notes, ideas, or dates…" value="${esc(state.noteSearch)}"><div class="notebook-layout"><div class="note-list" id="note-list">${list.length?list.map(x=>notePreview(x,n?.id)).join(''):'<div class="empty"><p>No thoughts here yet. Begin with a question.</p></div>'}</div><div id="note-edit-area">${n?noteEditor(n):'<div class="empty"><h2>A place for your own words.</h2><p>Keep a question from a reading, describe an everyday example, or return to a thought that changed.</p><button class="button" data-action="new-note">Write something down</button></div>'}</div></div><p class="notebook-help">Notes save automatically while you write. Your browser may clear local data if storage is removed. Export a backup to keep another copy; reinstalling on a different address creates a separate notebook.</p><div class="reading-tools"><button class="button secondary" data-action="export-backup">Export notes & progress</button><button class="button secondary" data-action="import-backup">Import a backup</button><button class="button secondary" data-action="export-markdown">Export notes as text</button></div>`;}
function notePreview(n,current){return `<a class="note-preview ${n.id===current?'active':''}" href="#/notebook/${encodeURIComponent(n.id)}"><h3>${esc(n.title||'Untitled thought')}</h3><p>${esc(n.body||'Room for a thought…')}</p><small>${esc(niceDate(n.updated))}${n.lesson?' · '+esc(lessonById(n.lesson)?.title||n.lesson):''}</small></a>`;}
function noteEditor(n){const l=lessonById(n.lesson),section=n.section!=null?l?.sections[Number(n.section)]?.title:null;return `<article class="note-editor" data-note-id="${esc(n.id)}">${l?`<a class="note-source" href="#/read/${esc(l.id)}">↖ ${esc(l.title)}${section?' · '+esc(section):''}</a><p></p>`:''}<label class="form-label" for="note-title">Title</label><input id="note-title" class="note-title" maxlength="1000" value="${esc(n.title)}" placeholder="Give this thought a name"><label class="form-label" for="note-body">Your thought</label><textarea id="note-body" class="note-body" placeholder="What did you notice? What would you ask?">${esc(n.body)}</textarea><div class="note-editor-bottom"><span class="save-state" id="save-state">${state.saveError?'Not saved — keep this window open':'Saved on this device'}</span><div class="note-actions"><button class="button secondary" data-action="export-note" data-note="${esc(n.id)}">Export</button><button class="icon-button" data-action="delete-note" data-note="${esc(n.id)}" aria-label="Delete this note">✕</button></div></div></article>`;}

function notFound(){return `${pageHead('FOLLOW ANOTHER THREAD','This page is not here.','Your readings and notes are still available.')}<a class="button" href="#/home">Return home</a>`;}
function currentRoute(){return (location.hash.replace(/^#\/?/,'')||'home').split('/').map(p=>{try{return decodeURIComponent(p);}catch{return '';}});}
function render(){const [route,id]=currentRoute();if(modal.open)closeModal();$('#desktop-nav').innerHTML=navMarkup(route);$('#mobile-nav').innerHTML=navMarkup(route,true);$('#breadcrumb').textContent=route==='read'?'Guided readings / '+(lessonById(id)?.title||'A reading'):NAV.find(n=>n[0]===route)?.[1]||'Ludwig';main.innerHTML=route==='home'?renderHome():route==='readings'?renderReadings():route==='read'?renderReader(id):route==='explore'?renderExplore(id):route==='daily'?renderDaily():route==='glossary'?renderGlossary():route==='sources'?renderSources():route==='notebook'?renderNotebook(id):notFound();document.title=`${route==='read'?lessonById(id)?.title||'Reading':NAV.find(n=>n[0]===route)?.[1]||'A place to think'} · Ludwig`;if(route==='explore'&&id&&$('#experiment-stage'))mountExperiment($('#experiment-stage'),id);window.scrollTo(0,0);main.focus({preventScroll:true});if(!state.storage&&!$('#storage-warning')){const warning=document.createElement('div');warning.id='storage-warning';warning.className='warning-note';warning.textContent='Your browser is blocking local storage. Readings work, but your notes cannot be saved until storage is available.';main.prepend(warning);}}

async function newNote({lesson=null,section=null,title='',body=''}={}){if(!state.storage){toast('Enable browser storage to save notes.');return;}const now=new Date().toISOString();const l=lessonById(lesson),selected=window.getSelection()?.toString()?.trim();const note={id:makeId(),title:title||l?.title||'A new thought',body:body||(selected?`“${selected.slice(0,15000)}”\n\n`:''),lesson,section,created:now,updated:now};try{await db.putNote(note);state.notes.push(note);if(modal.open)closeModal();location.hash='/notebook/'+encodeURIComponent(note.id);if(currentRoute()[0]==='notebook'&&currentRoute()[1]===note.id)render();setTimeout(()=>$('#note-body')?.focus(),50);}catch{toast('This note could not be saved. Device storage may be full.');}}

function queueNoteSave(){const editor=$('.note-editor');if(!editor)return;const note=state.notes.find(n=>n.id===editor.dataset.noteId);if(!note)return;note.title=$('#note-title').value;note.body=$('#note-body').value;note.updated=new Date().toISOString();const snapshot={...note},revision=(state.noteRevision||0)+1;state.noteRevision=revision;$('#save-state').textContent='Saving on this device…';state.saveQueue=state.saveQueue.catch(()=>{}).then(()=>db.putNote(snapshot)).then(()=>{state.saveError=false;if(revision===state.noteRevision&&$('#save-state')){$('#save-state').textContent='Saved on this device';$('#save-state').classList.remove('save-error');}}).catch(()=>{state.saveError=true;if($('#save-state')){$('#save-state').textContent='Not saved — export your note and keep this window open';$('#save-state').classList.add('save-error');}toast('Your note could not be saved. Export it to keep a copy.');});const preview=[...document.querySelectorAll('.note-preview')].find(el=>el.getAttribute('href')===`#/notebook/${encodeURIComponent(note.id)}`);if(preview){preview.querySelector('h3').textContent=note.title||'Untitled thought';preview.querySelector('p').textContent=note.body||'Room for a thought…';}}

function download(data,name,type){const blob=new Blob([data],{type});if(state.native){if(!window.ludwigExport?.postMessage){toast('Update Android System WebView to enable file export.');return;}const reader=new FileReader();reader.onload=()=>window.ludwigExport.postMessage(JSON.stringify({name,type,base64:String(reader.result).split(',')[1]}));reader.onerror=()=>toast('This file could not be prepared. Try again.');reader.readAsDataURL(blob);return;}const url=URL.createObjectURL(blob);const a=document.createElement('a');a.href=url;a.download=name;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),30000);}
async function exportBackup(){await state.saveQueue;download(JSON.stringify({app:'ludwig',version:1,exported:new Date().toISOString(),notes:state.notes,preferences:state.prefs},null,2),`ludwig-backup-${localDate()}.json`,'application/json');toast('Backup prepared. Save it somewhere you can find again.');}
function renderSearch(query=''){const results=[];if(query.trim()){
  for(const l of state.lessons)if(matchQuery(query,l.title,l.subtitle,l.summary,l.sections.map(s=>s.body)))results.push({type:'Reading',title:l.title,description:l.subtitle,url:`#/read/${l.id}`});
  for(const t of state.terms)if(matchQuery(query,t.german,t.english,t.definition,t.nuance))results.push({type:'Word & meaning',title:t.german,description:t.english,term:t.id});
  for(const s of state.sources)if(matchQuery(query,s.title,s.author,s.description,s.sections?.map(s=>s.summary)||[]))results.push({type:'Source',title:s.title,description:s.kind,source:s.id});
  for(const n of state.notes)if(matchQuery(query,n.title,n.body))results.push({type:'Your note',title:n.title,description:n.body.slice(0,140),url:`#/notebook/${encodeURIComponent(n.id)}`});
 }$('#search-results').innerHTML=!query.trim()?'<p class="muted">A word, a question, a passage, or a thought of your own.</p>':`<p class="search-result-count">${results.length} ${results.length===1?'result':'results'}</p>${results.slice(0,60).map(r=>`${r.url?`<a href="${r.url}"`:`<button data-action="${r.term?'term':'source-detail'}" data-${r.term?'term':'source'}="${esc(r.term||r.source)}"`} class="search-result"><small>${r.type}</small><h3>${esc(r.title)} ↗</h3><p>${esc(r.description)}</p>${r.url?'</a>':'</button>'}`).join('')}${!results.length?'<div class="empty">Try a shorter word, an English equivalent, or a neighboring idea.</div>':''}`;}
function openSearch(){openModal('Find a thread',`<label class="form-label" for="global-search">Search readings, meanings, sources, and your notes</label><input class="search-field" id="global-search" type="search" placeholder="How do I go on?" autocomplete="off"><div id="search-results"></div>`);renderSearch();setTimeout(()=>$('#global-search').focus(),30);}

async function settings(){const estimate=await navigator.storage?.estimate?.().catch(()=>null),persistent=await navigator.storage?.persisted?.().catch(()=>false);openModal('Make yourself at home',`<div class="settings-section"><h3>A place to read</h3><div class="settings-row"><label for="theme-setting">Appearance</label><select id="theme-setting"><option value="light" ${state.prefs.theme==='light'?'selected':''}>Daylight</option><option value="dark" ${state.prefs.theme==='dark'?'selected':''}>Lamplight</option><option value="system" ${state.prefs.theme==='system'?'selected':''}>Follow my device</option></select></div><div class="settings-row"><label for="font-setting">Reading text</label><select id="font-setting"><option value="normal" ${state.prefs.font==='normal'?'selected':''}>Comfortable</option><option value="large" ${state.prefs.font==='large'?'selected':''}>Large</option><option value="larger" ${state.prefs.font==='larger'?'selected':''}>Extra large</option></select></div><p><a class="text-link" href="#/glossary">Words & meanings ↗</a> · <a class="text-link" href="#/sources">The bookshelf ↗</a></p></div><div class="settings-section"><h3>Ludwig, without a connection</h3><p id="offline-detail">${state.offline?'✓ Readings, illustrations, glossary, and experiments are saved for offline use.':'The offline reading pack is still being prepared. Keep Ludwig open while connected.'}</p><p>Your notes and imported books are stored on this device. ${estimate?`This app currently uses about ${(estimate.usage/1024/1024).toFixed(1)} MB of local storage.`:''}</p><button class="button secondary" data-action="check-offline">Check offline readiness</button>${state.registration?.waiting?'<button class="button" data-action="update-app">Apply app update</button>':''}<button class="button secondary" data-action="persist-storage">${persistent?'✓ Persistent storage granted':'Ask device to keep local data'}</button><p class="fineprint">Even persistent storage can be removed in browser settings. Keep exported copies of notes and source files you value.</p></div><div class="settings-section"><h3>Keep Ludwig on your phone</h3>${state.installPrompt?'<button class="button" data-action="install">Install Ludwig ↗</button>':''}<p>On Android: open Ludwig in Chrome, tap the browser menu (⋮), then <strong>Install app</strong> or <strong>Add to Home screen</strong>. On iPhone: use Safari’s Share menu, then <strong>Add to Home Screen</strong>. On desktop: use your browser’s install button.</p><p>After the offline pack is ready, open Ludwig from its icon. An APK is optional; this version installs as a web app. The repository also includes an Android wrapper and build instructions.</p></div><div class="settings-section"><h3>Keep a second copy</h3><p>Export notes, bookmarks, and reading progress before moving devices or clearing browser data. Source imports are separate files and are not inside this backup.</p><button class="button secondary" data-action="export-backup">Export notes & progress</button><button class="button secondary" data-action="import-backup">Import a backup</button></div><div class="settings-section"><h3>Private, by design</h3><p>No account inside the app. No analytics, cloud notebook, remote fonts, or AI requests. The app uses the network to download itself and check for updates; your notes and imported files remain local. Opening an original source link leaves the app and uses that service.</p><p>Explanations and experiments are original educational commentary. Source-specific cautions appear in the bookshelf. Images are artistic interpretations, not historical documents.</p></div>`);}

async function checkOffline(){if(state.native){state.offline=true;updateOfflineLabel();if($('#offline-detail'))$('#offline-detail').textContent='✓ The reading pack is bundled inside this Android app.';return;}if(!state.registration?.active){state.offline=false;updateOfflineLabel();return;}try{const channel=new MessageChannel();const result=await new Promise((resolve,reject)=>{const timeout=setTimeout(()=>reject(new Error('No service worker response.')),5000);channel.port1.onmessage=e=>{clearTimeout(timeout);resolve(e.data);};state.registration.active.postMessage({type:'OFFLINE_STATUS'},[channel.port2]);});state.offline=!!result.ready;}catch{state.offline=false;}updateOfflineLabel();if($('#offline-detail'))$('#offline-detail').textContent=state.offline?'✓ The complete reading pack is saved for offline use.':'The reading pack is incomplete. Reconnect and reload to prepare it.';}
function updateOfflineLabel(){document.body.classList.toggle('offline-ready',state.offline);$('#offline-label').textContent=state.offline?'Ready to wander offline':('serviceWorker' in navigator?'Preparing offline reading':'Offline pack unavailable here');}

async function openFile(id){const stored=await db.getFile(id);if(!stored){toast('Import your copy first.');return;}const source=state.sources.find(s=>s.id===id);if(stored.name.toLowerCase().endsWith('.epub')){openModal('Your local copy',`<h2>${esc(source?.title||stored.name)}</h2><p>Opening your EPUB on this device…</p>`);const revision=state.modalRevision;try{const book=await readEpub(stored.blob);if(!modal.open||revision!==state.modalRevision)return;let chapter=0;const draw=()=>{$('#modal-body').innerHTML=`<h2 style="font-size:28px">${esc(book.title)}</h2><p class="fineprint">Local text reader · images, complex equations, and original typography are not reproduced. Use your usual reader for the original layout.</p><div class="epub-controls"><button class="button secondary" id="epub-prev" ${chapter===0?'disabled':''}>←</button><label class="form-label" style="display:none" for="epub-chapter">Chapter</label><select id="epub-chapter">${book.chapters.map((c,i)=>`<option value="${i}" ${i===chapter?'selected':''}>${i+1}. ${esc(c.title.slice(0,80))}</option>`).join('')}</select><button class="button secondary" id="epub-next" ${chapter===book.chapters.length-1?'disabled':''}>→</button></div><article class="epub-prose" id="epub-prose">${book.chapters[chapter].html}</article><div class="modal-actions"><button class="button secondary" data-action="download-source" data-source="${esc(id)}">Open with my usual reader</button></div>`;$('#epub-prev').onclick=()=>{chapter=Math.max(0,chapter-1);draw();};$('#epub-next').onclick=()=>{chapter=Math.min(book.chapters.length-1,chapter+1);draw();};$('#epub-chapter').onchange=e=>{chapter=Number(e.target.value);draw();};};if(modal.open)draw();}catch(e){if(!modal.open||revision!==state.modalRevision)return;openModal('Your local copy',`<h2>This EPUB needs your usual reader.</h2><p>${esc(e.message)}</p><button class="button" data-action="download-source" data-source="${esc(id)}">Open a copy ↗</button>`);}return;}
 openModal('Your local copy',`<h2 style="font-size:28px">${esc(source?.title||stored.name)}</h2><p class="fineprint">If your browser does not show PDFs here, open a copy in your usual reader. Printed pages and PDF pages can differ.</p><div id="pdf-container"></div><div class="modal-actions"><button class="button secondary" data-action="download-source" data-source="${esc(id)}">Open with my usual reader</button></div>`);const url=URL.createObjectURL(stored.blob);state.objectUrls.push(url);const frame=document.createElement('iframe');frame.className='source-reader';frame.title=source?.title||stored.name;frame.src=url;$('#pdf-container').append(frame);
}

document.addEventListener('click',async event=>{
 const target=event.target.closest('[data-action]');if(!target)return;const action=target.dataset.action;if(target.tagName==='A')event.preventDefault();
 try{
 if(action==='close-modal')closeModal();
 else if(action==='search')openSearch();
 else if(action==='settings'||action==='reader-settings')await settings();
 else if(action==='filter'){state.filter=target.dataset.filter;const scroll=window.scrollY;main.innerHTML=renderReadings();window.scrollTo(0,scroll);}
 else if(action==='term')showTerm(target.dataset.term);
 else if(action==='citation'||action==='source-detail')sourceDetail(target.dataset.source,target.dataset.locator,target.dataset.note);
 else if(action==='bookmark'){const id=target.dataset.lesson;state.prefs.bookmarks=state.prefs.bookmarks.includes(id)?state.prefs.bookmarks.filter(x=>x!==id):[...state.prefs.bookmarks,id];await savePrefs();target.textContent=state.prefs.bookmarks.includes(id)?'✓ Saved reading':'＋ Save reading';}
 else if(action==='complete'){const id=target.dataset.lesson;if(!state.prefs.completed.includes(id)){state.prefs.completed.push(id);await savePrefs();}target.textContent='✓ Marked as explored';toast('A thought to carry with you.');}
 else if(action==='scroll-section')document.getElementById(target.dataset.section)?.scrollIntoView({behavior:matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});
 else if(action==='new-note'||action==='experiment-note')await newNote({lesson:target.dataset.lesson||null});
 else if(action==='section-note'){const l=lessonById(target.dataset.lesson);await newNote({lesson:l.id,section:target.dataset.section,title:l.sections[Number(target.dataset.section)].title});}
 else if(action==='term-note'){const t=termById(target.dataset.term);await newNote({title:`${t.german} · ${t.english}`,body:`What does this distinction help me see?\n\n`});}
 else if(action==='reflection'){const l=lessonById(target.dataset.lesson);await newNote({lesson:l.id,title:`Reflecting · ${l.title}`,body:l.exercise.reflection+'\n\n'});}
 else if(action==='daily-note'){const existing=state.notes.find(n=>n.title===`Daily thought · ${localDate()}`);if(existing){location.hash='/notebook/'+encodeURIComponent(existing.id);}else{const l=lessonById(target.dataset.lesson);await newNote({lesson:l.id,title:`Daily thought · ${localDate()}`,body:l.questions[dailyIndex(l.questions.length)]+'\n\n'+l.exercise.reflection+'\n\n'});}}
 else if(action==='exercise-answer'){const l=lessonById(target.dataset.lesson),o=l.exercise.options[Number(target.dataset.option)];$('#exercise-feedback').innerHTML=`<div class="feedback">${esc(o.feedback)}</div>`;document.querySelectorAll('[data-action="exercise-answer"]').forEach(b=>b.classList.toggle('selected',b===target));}
 else if(action==='delete-note'){const n=state.notes.find(n=>n.id===target.dataset.note);openModal('Remove a thought?',`<h2>Delete “${esc(n.title||'Untitled thought')}”?</h2><p>This removes the note from this device. Export it first if you want to keep a copy.</p><div class="modal-actions"><button class="button secondary" data-action="close-modal">Keep note</button><button class="button danger" data-action="confirm-delete-note" data-note="${esc(n.id)}">Delete this note</button></div>`);}
 else if(action==='confirm-delete-note'){await state.saveQueue;await db.deleteNote(target.dataset.note);state.notes=state.notes.filter(n=>n.id!==target.dataset.note);closeModal();location.hash='/notebook';render();toast('Note removed from this device.');}
 else if(action==='export-backup')await exportBackup();
 else if(action==='import-backup')$('#backup-input').click();
 else if(action==='export-markdown')download(state.notes.map(noteMarkdown).join('\n\n\n'),`ludwig-notes-${localDate()}.md`,'text/markdown');
 else if(action==='export-note'){const n=state.notes.find(n=>n.id===target.dataset.note);download(noteMarkdown(n),`ludwig-note-${localDate()}.md`,'text/markdown');}
 else if(action==='import-source'){state.sourceTarget=target.dataset.source;$('#source-input').value='';$('#source-input').click();}
 else if(action==='open-file')await openFile(target.dataset.source);
 else if(action==='remove-file'){const id=target.dataset.source;openModal('Remove local source?',`<h2>Remove your imported copy?</h2><p>The original file in your Drive and any notes you wrote remain available.</p><div class="modal-actions"><button class="button secondary" data-action="close-modal">Keep copy</button><button class="button danger" data-action="confirm-remove-file" data-source="${esc(id)}">Remove from this device</button></div>`);}
 else if(action==='confirm-remove-file'){await db.deleteFile(target.dataset.source);state.files=state.files.filter(id=>id!==target.dataset.source);closeModal();if(currentRoute()[0]==='sources')render();toast('Local source copy removed.');}
 else if(action==='download-source'){const f=await db.getFile(target.dataset.source);if(f)download(f.blob,f.name,f.blob.type);}
 else if(action==='copy-citation'){const s=state.sources.find(s=>s.id===target.dataset.source);const text=`${s.author} (${s.year}). ${s.title}. ${s.edition}${target.dataset.locator?' Cited passage: '+target.dataset.locator+'.':''}`;try{await navigator.clipboard.writeText(text);toast('Reference copied. Check your required citation style.');}catch{openModal('Copy this reference',`<textarea class="modal-note" readonly>${esc(text)}</textarea>`);}}
 else if(action==='check-offline'){await checkOffline();toast(state.offline?'The complete reading pack is ready offline.':'Reconnect and reload to finish the reading pack.');}
 else if(action==='persist-storage'){const granted=await navigator.storage?.persist?.();target.textContent=granted?'✓ Persistent storage granted':'Keep exporting backups';toast(granted?'The browser agreed to retain local data.':'This browser decides storage retention automatically. Export backups.');}
 else if(action==='install'){if(state.installPrompt){await state.installPrompt.prompt();await state.installPrompt.userChoice;state.installPrompt=null;await settings();}}
 else if(action==='update-app'){await state.saveQueue;state.registration?.waiting?.postMessage({type:'SKIP_WAITING'});}
 }catch(e){console.error('Ludwig action failed:',e);toast('That action could not finish. Your current text is still here.');}
});

document.addEventListener('input',event=>{const el=event.target;if(el.id==='global-search')renderSearch(el.value);else if(el.id==='reading-search'){state.readingSearch=el.value;const list=state.lessons.filter(l=>(state.filter==='All'||(state.filter==='Saved'?state.prefs.bookmarks.includes(l.id):l.category===state.filter))&&matchQuery(state.readingSearch,l.title,l.subtitle,l.summary,l.category,l.period));$('#reading-results').innerHTML=list.length?list.map(lessonCard).join(''):'<div class="empty">No matching readings. Try another word.</div>';}else if(el.id==='glossary-search'){state.glossarySearch=el.value;const list=state.terms.filter(t=>matchQuery(el.value,t.german,t.english,t.definition,t.nuance));$('#term-results').innerHTML=list.length?list.map(termCard).join(''):'<div class="empty">No matching terms.</div>';}else if(el.id==='note-search'){state.noteSearch=el.value;const list=state.notes.filter(n=>matchQuery(el.value,n.title,n.body,n.lesson,n.updated)).sort((a,b)=>b.updated.localeCompare(a.updated));$('#note-list').innerHTML=list.length?list.map(n=>notePreview(n,$('.note-editor')?.dataset.noteId)).join(''):'<div class="empty">No matching thoughts.</div>';}else if(el.id==='note-title'||el.id==='note-body')queueNoteSave();});
document.addEventListener('change',async event=>{if(event.target.id==='theme-setting'){state.prefs.theme=event.target.value;await savePrefs();}if(event.target.id==='font-setting'){state.prefs.font=event.target.value;await savePrefs();}});
document.addEventListener('keydown',e=>{if((e.metaKey||e.ctrlKey)&&e.key.toLowerCase()==='k'){e.preventDefault();openSearch();}});
window.addEventListener('hashchange',render);
window.addEventListener('beforeunload',event=>{if(state.saveError){event.preventDefault();event.returnValue='';}});
window.addEventListener('scroll',()=>{const p=$('#reading-progress');if(p){const max=document.documentElement.scrollHeight-innerHeight;p.style.width=Math.min(100,max>0?scrollY/max*100:100)+'%';}},{passive:true});
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(state.prefs.theme==='system')applyPrefs();});
window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();state.installPrompt=e;});

$('#backup-input').addEventListener('change',async event=>{const file=event.target.files[0];if(!file)return;try{if(file.size>25000000)throw new Error('This backup is too large.');const data=validateBackup(JSON.parse(await file.text()));await state.saveQueue;const notes=mergeNotes(state.notes,data.notes),prefs={...state.prefs,...data.preferences,completed:[...new Set([...state.prefs.completed,...data.preferences.completed||[]])],bookmarks:[...new Set([...state.prefs.bookmarks,...data.preferences.bookmarks||[]])]};await db.importBackupAtomic(notes,prefs);state.notes=notes;state.prefs=prefs;applyPrefs();if(modal.open)closeModal();location.hash='/notebook';render();toast(`Backup merged. ${data.notes.length} notes checked; existing newer notes kept.`);}catch(e){toast(e.message==='Unexpected end of JSON input'?'This backup is incomplete. No notes were imported.':e.message||'This backup could not be imported.');}event.target.value='';});
$('#source-input').addEventListener('change',async event=>{const file=event.target.files[0];if(!file||!state.sourceTarget)return;try{if(file.size>100000000)throw new Error('Please import a file under 100 MB.');if(!/\.(pdf|epub)$/i.test(file.name))throw new Error('Choose a PDF or EPUB.');const header=new Uint8Array(await file.slice(0,5).arrayBuffer());const pdf=/\.pdf$/i.test(file.name);if(pdf?new TextDecoder().decode(header)!=='%PDF-':header[0]!==80||header[1]!==75)throw new Error('The file contents do not match its extension.');await db.putFile({id:state.sourceTarget,name:file.name,blob:new Blob([file],{type:pdf?'application/pdf':'application/epub+zip'}),imported:new Date().toISOString()});state.files=await db.getFileKeys();if(modal.open)closeModal();if(currentRoute()[0]==='sources')render();toast('Your copy is saved on this device.');}catch(e){toast(e.message||'Could not import this copy. Storage may be full.');}});

async function init(){try{const responses=await Promise.all(['lessons','glossary','sources'].map(name=>fetch(`./data/${name}.json`).then(r=>{if(!r.ok)throw new Error(`Missing ${name}`);return r.json();})));[state.lessons,state.terms,state.sources]=responses;try{const [notes,prefs,files]=await Promise.all([db.getNotes(),db.getPreferences(),db.getFileKeys()]);state.notes=notes;state.prefs={...state.prefs,...prefs};state.files=files;}catch{state.storage=false;}applyPrefs();render();if(state.native){state.offline=true;updateOfflineLabel();return;}if('serviceWorker' in navigator){try{state.registration=await navigator.serviceWorker.register('./sw.js');navigator.serviceWorker.addEventListener('controllerchange',()=>{if(state.updating)location.reload();else void checkOffline();});state.registration.addEventListener('updatefound',()=>{const installing=state.registration.installing;installing?.addEventListener('statechange',()=>{if(installing.state==='installed'){void checkOffline();if(navigator.serviceWorker.controller)toast('An update is ready. Apply it in settings when you are ready.');}});});await navigator.serviceWorker.ready;await checkOffline();if(!state.offline)setTimeout(()=>void checkOffline(),1500);}catch{state.registration=await navigator.serviceWorker.getRegistration('./').catch(()=>null);await checkOffline();}}else updateOfflineLabel();}catch(e){main.innerHTML=`<div class="error-box"><h1>We couldn’t open the reading pack.</h1><p>If this is your first visit, connect to the internet and reload. If you were reading offline, reconnect once to finish downloading the app.</p><button class="button" onclick="location.reload()">Try again</button></div>`;console.error(e);}}
document.addEventListener('click',e=>{if(e.target.closest('[data-action="update-app"]'))state.updating=true;});
void init();
